$path = (Resolve-Path 'wwwroot/app.js')
$source = [IO.File]::ReadAllText($path, [Text.Encoding]::UTF8)
$detail = @'
function openDetail(id){const x=items.find(i=>i.id===id);if(!x)return;selected=x;const image=x.assets?.find(a=>a.kind==='image'),model=x.assets?.find(a=>a.kind==='model'),drawing=x.assets?.find(a=>a.kind==='drawing');const href=a=>`/files/${encodeURIComponent(a.storedName)}`;const content=`<div class="modal-content"><div class="product-document"><section class="document-render">${image?`<img src="${href(image)}" alt="Рендер ${esc(x.name)}">`:`<div class="image-placeholder">Рендер не загружен</div>`}<div class="render-caption">РЕНДЕР · ${esc(x.number)}</div></section><div class="document-heading"><div><div class="detail-category">${esc(x.category)}</div><h2 class="detail-number">${esc(x.name||'Изделие МАФ')}</h2><div class="detail-name">Заказ № ${esc(x.orderNumber||x.number?.split('.')[0]||'—')} · изделие № ${esc(x.productNumber||x.number?.split('.')[1]||'—')} <span class="document-size">${esc(x.dimensions||'')}</span></div></div><div class="document-actions">${model?`<a class="button primary" href="${href(model)}" target="_blank" rel="noopener">◉ 3D</a>`:''}${drawing?`<a class="button" href="${href(drawing)}" download="${esc(drawing.name)}">↓ Скачать PDF</a>`:''}${editing?`<button class="button" id="editDetails">Изменить</button>`:''}</div></div>${x.notes?`<p class="document-notes">${esc(x.notes)}</p>`:''}${drawing?`<section class="drawing-page"><div class="drawing-toolbar"><span>ЧЕРТЁЖ · ${esc(drawing.name)}</span><a href="${href(drawing)}" download="${esc(drawing.name)}">↓ Скачать PDF</a></div><iframe title="Чертёж ${esc(drawing.name)}" src="${href(drawing)}#view=FitH" loading="lazy"></iframe></section>`:`<div class="no-drawing">Чертёж PDF ещё не загружен.</div>`}${editing?`<div class="replace-files"><div class="section-label">Добавить или заменить файлы</div><div class="upload-row"><input type="file" id="uploadFiles" multiple accept=".html,.htm,.png,.jpg,.jpeg,.webp,.gif,.pdf"><button class="button primary" id="uploadButton">Загрузить</button></div><div>${(x.assets||[]).map(a=>`<div class="asset-manage"><span>${esc(a.kind)} · ${esc(a.name)} · ${formatSize(a.size)}</span><button class="delete-asset" data-delete-asset="${a.id}">Удалить</button></div>`).join('')}</div></div>`:''}</div>`;const actions=`<footer class="modal-actions"><span>${x.sourcePath?`<button class="button" id="copyPath">Копировать исходный путь</button>`:''}</span><button class="button" id="detailClose">Закрыть</button></footer>`;modal(esc(x.number)+' · '+esc(x.name||'Карточка изделия'),`${esc(x.category)} · материалы изделия`,content,actions,'product-detail-modal');$('#detailClose').onclick=closeModal;if(editing)$('#editDetails').onclick=()=>editor(x);if(x.sourcePath)$('#copyPath').onclick=async()=>{try{await navigator.clipboard.writeText(x.sourcePath);toast('Сетевой путь скопирован')}catch{toast(x.sourcePath)}};root.querySelectorAll('[data-delete-asset]').forEach(b=>b.onclick=async()=>{if(!confirm('Удалить этот файл?'))return;try{await api(`/api/items/${x.id}/files/${b.dataset.deleteAsset}`,{method:'DELETE'});await refresh();openDetail(x.id);toast('Файл удалён')}catch{toast('Не удалось удалить файл')}});if(editing)$('#uploadButton').onclick=async()=>{const files=[...$('#uploadFiles').files];if(!files.length){toast('Выберите файлы для загрузки');return}for(const f of files){const fd=new FormData();fd.append('file',f);try{await api(`/api/items/${x.id}/files`,{method:'POST',body:fd})}catch(e){toast(`Ошибка загрузки ${f.name}`);return}}await refresh();openDetail(x.id);toast('Файлы загружены')}}
'@
$rx = [regex]::new('function openDetail\(id\)\{.*?function assetLink', [Text.RegularExpressions.RegexOptions]::Singleline)
if (-not $rx.IsMatch($source)) { throw 'openDetail not found' }
$source = $rx.Replace($source, $detail + 'function assetLink', 1)
[IO.File]::WriteAllText($path, $source, [Text.UTF8Encoding]::new($false))
